import{_ as s,o as t,c as i,ag as n}from"./chunks/framework.C9sp7nFj.js";const g=JSON.parse('{"title":"Hand 切换SCARA手系","description":"","frontmatter":{},"headers":[],"relativePath":"3. 指令/5. 设置指令/Hand.md","filePath":"3. 指令/5. 设置指令/Hand.md","lastUpdated":1778862643000}'),e={name:"3. 指令/5. 设置指令/Hand.md"};function r(h,a,o,d,l,p){return t(),i("div",null,[...a[0]||(a[0]=[n(`<h1 id="hand-切换scara手系" tabindex="-1">Hand 切换SCARA手系 <a class="header-anchor" href="#hand-切换scara手系" aria-label="Permalink to &quot;Hand 切换SCARA手系&quot;">​</a></h1><p>该指令专用于 <strong>SCARA 机器人</strong>，用于<strong>切换机器人的关节构型（左手系或右手系）</strong>。SCARA 机器人独特的机械结构使得末端 TCP 可以在不改变位置的情况下，通过第一、二轴的不同折叠方向（左折或右折）来抵达同一点位。</p><h2 id="指令格式" tabindex="-1">指令格式 <a class="header-anchor" href="#指令格式" aria-label="Permalink to &quot;指令格式&quot;">​</a></h2><p>Hand(st) Hand(左右手类型)</p><hr><h2 id="参数详细说明" tabindex="-1">参数详细说明 <a class="header-anchor" href="#参数详细说明" aria-label="Permalink to &quot;参数详细说明&quot;">​</a></h2><table tabindex="0"><thead><tr><th>参数</th><th>类型</th><th>说明</th><th>默认值/备注</th></tr></thead><tbody><tr><td>st：左右手设置类型（Set Type）</td><td>enum（枚举型）</td><td>定义机器人关节的折叠倾向。<br>* <strong>Lefty</strong>：<strong>左手系</strong>。从机器人上方俯视，第一、二轴向左侧弯折。<br>* <strong>Righty</strong>：<strong>右手系</strong>。从机器人上方俯视，第一、二轴向右侧弯折。<br>* <strong>Default</strong>：<strong>默认设置</strong>。通常遵循示教点位原始记录的构型，或系统缺省配置。</td><td></td></tr></tbody></table><hr><h2 id="工作原理" tabindex="-1">工作原理 <a class="header-anchor" href="#工作原理" aria-label="Permalink to &quot;工作原理&quot;">​</a></h2><p>在执行 <code>MovJCpos</code> 等关节空间运动指令时，<code>Hand</code> 指令会强制机器人改变其物理姿态。这种切换对于避开工作空间内的障碍物或在狭窄区域内作业至关重要。</p><hr><h2 id="示例" tabindex="-1">示例： <a class="header-anchor" href="#示例" aria-label="Permalink to &quot;示例：&quot;">​</a></h2><div class="language-estun vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">estun</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">Hand</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;Lefty&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">)</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">MovJCpos</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(</span><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;">P1</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;"> 100</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;"> 0</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;"> 1</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">)</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br></div></div><p><strong>执行结果：</strong></p><p>机器人将以<strong>左手姿态</strong>移动到目标点 <strong>P1</strong>。即使 P1 在示教时是右手姿态，执行此指令后，机器人也会在运动过程中自动切换为左手姿态。</p><hr><h2 id="应用场景" tabindex="-1">应用场景 <a class="header-anchor" href="#应用场景" aria-label="Permalink to &quot;应用场景&quot;">​</a></h2><ul><li><strong>避障规划</strong>：当工作台右侧有围栏或支架时，通过 <code>Hand(&quot;Lefty&quot;)</code> 让机器人肢体向左侧收缩，从而避免碰撞。</li><li><strong>扩大作业范围</strong>：某些点位在右手姿态下可能达到关节限位，切换为左手姿态则可以顺利抵达。</li><li><strong>对称工位作业</strong>：在左右对称的流水线上，通过切换手系可以直接复用同一套逻辑代码。</li></ul>`,18)])])}const c=s(e,[["render",r]]);export{g as __pageData,c as default};
